vulnerable_code:
app.get('/api/users/:uid/profile/:itemId', async (req, res) => {
  const item = await Profile.findById(req.params.itemId);
  res.json(item);
});

corrected_code:
app.get('/api/users/:uid/profile/:itemId', async (req, res) => {
  if (req.user.id !== req.params.uid) return res.status(403).send('Forbidden');
  const item = await Profile.findOne({ _id: req.params.itemId, userId: req.user.id });
  res.json(item);
});
